1	// This file implements the organization-scoped audit chain. Every successful
2	// policy publish or rollback, and every Decide called with a non-empty
3	// decision organization, leaves an immutable record in that organization.
4	//
5	// Records carry an organization-local sequence starting at 1 and a SHA-256
6	// fingerprint that chains each record to the previous one. The genesis
7	// fingerprint binds the organization name, so records from another
8	// organization can never validate as part of this chain even when the
9	// sequence numbers and identifiers coincide.
10	package darksafe
11	
12	import (
13		"crypto/sha256"
14		"encoding/hex"
15		"encoding/json"
16		"errors"
17		"fmt"
18	)
19	
20	// Audit record categories.
21	const (
22		// AuditPolicyChange is a successful publish or rollback.
23		AuditPolicyChange = "policy_change"
24		// AuditDecision is one Decide evaluation.
25		AuditDecision = "decision"
26	)
27	
28	// Sentinel errors for the audit entry points. Callers distinguish them
29	// with errors.Is; every one leaves state unchanged.
30	var (
31		// ErrInvalidPage means a page size or range argument was invalid.
32		ErrInvalidPage = errors.New("darksafe: invalid audit page")
33		// ErrInvalidRange means the upper bound is beyond what exists, the
34		// range is inverted, or a supplied fingerprint does not match.
35		ErrInvalidRange = errors.New("darksafe: invalid audit range")
36		// ErrAuditNotFound means no record exists at the requested sequence.
37		ErrAuditNotFound = errors.New("darksafe: audit record not found")
38		// ErrAuditNotADecision means the record at the sequence is not a
39		// decision record and therefore cannot be rechecked.
40		ErrAuditNotADecision = errors.New("darksafe: audit record is not a decision")
41	)
42	
43	// PolicyChange captures a successful publish or rollback.
44	type PolicyChange struct {
45		// Version is the newly created policy version.
46		Version int
47		// Policies is the full policy set of the new version.
48		Policies []Policy
49		// SourceVersion is the version copied by a rollback, and 0 for an
50		// ordinary publish.
51		SourceVersion int
52		// RolledBack reports whether the change was produced by Rollback.
53		RolledBack bool
54	}
55	
56	// DecisionRecord captures one Decide call: the full request and the
57	// decision actually returned.
58	type DecisionRecord struct {
59		Request  OrgRequest
60		Decision Decision
61	}
62	
63	// AuditRecord is one immutable entry in an organization's audit chain.
64	type AuditRecord struct {
65		Org      string
66		Seq      int // organization-local, starting at 1 and gapless
67		Kind     string
68		Change   *PolicyChange   // present when Kind == AuditPolicyChange
69		Decision *DecisionRecord // present when Kind == AuditDecision
70	
71		// PrevFingerprint is the fingerprint of the preceding record, or the
72		// genesis fingerprint for the first record.
73		PrevFingerprint string
74		// Fingerprint binds this record's full content to its predecessor.
75		Fingerprint string
76	}
77	
78	// hashEnvelope is the canonical, organization-bound representation that
79	// fingerprints are computed over. It is never exposed, so callers cannot
80	// forge one by constructing an AuditRecord with copied fields.
81	type hashEnvelope struct {
82		Org             string          `json:"org"`
83		Seq             int             `json:"seq"`
84		Kind            string          `json:"kind"`
85		Change          *PolicyChange   `json:"change,omitempty"`
86		Decision        *DecisionRecord `json:"decision,omitempty"`
87		PrevFingerprint string          `json:"prev"`
88	}
89	
90	// genesisFingerprint derives the chain root from the organization name,
91	// keeping equal identifiers in different organizations independent.
92	func genesisFingerprint(org string) string {
93		sum := sha256.Sum256([]byte("darksafe-audit-genesis\x00" + org))
94		return hex.EncodeToString(sum[:])
95	}
96	
97	// computeFingerprint returns the fingerprint for an envelope.
98	func computeFingerprint(e *hashEnvelope) string {
99		b, err := json.Marshal(e)
100		if err != nil {
101			// All envelope fields are plain, JSON-encodable values; a failure
102			// here indicates a programming error, not user input.
103			panic(fmt.Errorf("darksafe: audit envelope must encode: %w", err))
104		}
105		sum := sha256.Sum256(b)
106		return hex.EncodeToString(sum[:])
107	}
108	
109	// fingerprintFor builds and fingerprints the envelope for a record.
110	func fingerprintFor(r *AuditRecord) string {
111		return computeFingerprint(&hashEnvelope{
112			Org:             r.Org,
113			Seq:             r.Seq,
114			Kind:            r.Kind,
115			Change:          r.Change,
116			Decision:        r.Decision,
117			PrevFingerprint: r.PrevFingerprint,
118		})
119	}
120	
121	// clonePolicies returns a detached copy of a policy set.
122	func clonePolicies(in []Policy) []Policy {
123		if in == nil {
124			return nil
125		}
126		return append([]Policy(nil), in...)
127	}
128	
129	// cloneChange returns a detached copy of a policy-change payload.
130	func cloneChange(c *PolicyChange) *PolicyChange {
131		if c == nil {
132			return nil
133		}
134		cp := *c
135		cp.Policies = clonePolicies(c.Policies)
136		return &cp
137	}
138	
139	// cloneDecision returns a detached copy of a decision payload.
140	func cloneDecision(d *DecisionRecord) *DecisionRecord {
141		if d == nil {
142			return nil
143		}
144		cp := *d
145		if len(d.Decision.Matched) > 0 {
146			cp.Decision.Matched = append([]string(nil), d.Decision.Matched...)
147		}
148		if len(d.Request.Subject.Roles) > 0 {
149			cp.Request.Subject.Roles = append([]string(nil), d.Request.Subject.Roles...)
150		}
151		return &cp
152	}
153	
154	// cloneRecord returns a fully detached copy of a record.
155	func cloneRecord(r *AuditRecord) *AuditRecord {
156		cp := *r
157		cp.Change = cloneChange(r.Change)
158		cp.Decision = cloneDecision(r.Decision)
159		return &cp
160	}
161	
162	// appendAuditLocked validates, fingerprints and stores one record. It runs
163	// under the store mutex and is the single place records are created.
164	func (st *orgState) appendAuditLocked(org, kind string, change *PolicyChange, decision *DecisionRecord) *AuditRecord {
165		seq := len(st.audit) + 1
166		prev := genesisFingerprint(org)
167		if len(st.audit) > 0 {
168			prev = st.audit[len(st.audit)-1].Fingerprint
169		}
170		// Store detached copies; later caller mutation must not reach the chain.
171		rec := &AuditRecord{
172			Org:             org,
173			Seq:             seq,
174			Kind:            kind,
175			Change:          cloneChange(change),
176			Decision:        cloneDecision(decision),
177			PrevFingerprint: prev,
178		}
179		rec.Fingerprint = fingerprintFor(rec)
180		st.audit = append(st.audit, rec)
181		return cloneRecord(rec)
182	}
183	
184	// auditHeadLocked returns the highest sequence in the chain and the
185	// fingerprint that covers it: (0, genesis) for an organization with no
186	// records.
187	func (st *orgState) auditHeadLocked(org string) (int, string) {
188		if len(st.audit) == 0 {
189			return 0, genesisFingerprint(org)
190		}
191		last := st.audit[len(st.audit)-1]
192		return last.Seq, last.Fingerprint
193	}
194	
195	// Checkpoint pins an audit query to an exact point in a chain.
196	type Checkpoint struct {
197		Org         string
198		EndSeq      int
199		Fingerprint string
200	}
201	
202	// AuditPage is one stable slice of an organization's audit chain.
203	type AuditPage struct {
204		Org     string
205		Records []AuditRecord
206		// BeginSeq/EndSeq delimit the whole pinned range, not just this page.
207		BeginSeq int
208		EndSeq   int
209		// Next is the first sequence of the following page, 0 when exhausted.
210		Next int
211		// Checkpoint is the pinned upper bound shared by every page.
212		Checkpoint Checkpoint
213	}
214	
215	// recordMatches reports whether a record survives the query filters.
216	func recordMatches(r *AuditRecord, kind, subjectID string) bool {
217		if kind != "" && r.Kind != kind {
218			return false
219		}
220		if subjectID != "" {
221			// A subject filter selects decision records of that subject only.
222			if r.Kind != AuditDecision || r.Decision == nil ||
223				r.Decision.Request.Subject.ID != subjectID {
224				return false
225			}
226		}
227		return true
228	}
229	
230	// AuditQuery pins the first page of an audit query. startSeq is the first
231	// sequence considered (1 from the beginning); endSeq <= 0 means "everything
232	// currently stored". The returned checkpoint must be passed to AuditPage
233	// for the following pages, so records appended after the first query never
234	// mix into later pages.
235	func (s *Store) AuditQuery(org string, startSeq, pageSize int, kind, subjectID string) (*AuditPage, error) {
236		if org == "" {
237			return nil, ErrMissingOrganization
238		}
239		if kind != "" && kind != AuditPolicyChange && kind != AuditDecision {
240			return nil, fmt.Errorf("%w: unknown category %q", ErrInvalidPage, kind)
241		}
242		if pageSize <= 0 {
243			return nil, fmt.Errorf("%w: page size must be positive, got %d", ErrInvalidPage, pageSize)
244		}
245		if startSeq < 1 {
246			return nil, fmt.Errorf("%w: start sequence must be >= 1, got %d", ErrInvalidPage, startSeq)
247		}
248		s.mu.Lock()
249		defer s.mu.Unlock()
250		st := s.orgLocked(org)
251		end, fingerprint := st.auditHeadLocked(org)
252		cp := Checkpoint{Org: org, EndSeq: end, Fingerprint: fingerprint}
253		if end == 0 {
254			// An organization with no records always yields the empty genesis
255			// page, regardless of where the caller asked to begin.
256			return &AuditPage{Org: org, BeginSeq: 1, EndSeq: 0, Checkpoint: cp}, nil
257		}
258		if startSeq > end {
259			return nil, fmt.Errorf("%w: start sequence %d is beyond end sequence %d", ErrInvalidRange, startSeq, end)
260		}
261		return s.auditPageLocked(org, startSeq, end, fingerprint, pageSize, kind, subjectID), nil
262	}
263	
264	// AuditPage returns one page of a previously pinned query. nextSeq is the
265	// cursor from the previous page; when it is 0 the range is exhausted. The
266	// checkpoint is re-verified against the chain on every call.
267	func (s *Store) AuditPage(cp Checkpoint, nextSeq, pageSize int, kind, subjectID string) (*AuditPage, error) {
268		if cp.Org == "" {
269			return nil, ErrMissingOrganization
270		}
271		if kind != "" && kind != AuditPolicyChange && kind != AuditDecision {
272			return nil, fmt.Errorf("%w: unknown category %q", ErrInvalidPage, kind)
273		}
274		if pageSize <= 0 {
275			return nil, fmt.Errorf("%w: page size must be positive, got %d", ErrInvalidPage, pageSize)
276		}
277		if nextSeq < 0 {
278			return nil, fmt.Errorf("%w: next sequence must be >= 0, got %d", ErrInvalidPage, nextSeq)
279		}
280		s.mu.Lock()
281		defer s.mu.Unlock()
282		st, ok := s.orgs[cp.Org]
283		if !ok {
284			// No organization state: the only valid checkpoint is an empty one.
285			g := genesisFingerprint(cp.Org)
286			if cp.EndSeq == 0 && cp.Fingerprint == g && nextSeq == 0 {
287				return &AuditPage{Org: cp.Org, BeginSeq: 0, EndSeq: 0, Checkpoint: cp}, nil
288			}
289			return nil, fmt.Errorf("%w: checkpoint organization has no records", ErrInvalidRange)
290		}
291		head := len(st.audit)
292		if cp.EndSeq < 0 || cp.EndSeq > head {
293			return nil, fmt.Errorf("%w: end sequence %d beyond %d", ErrInvalidRange, cp.EndSeq, head)
294		}
295		wantFP := genesisFingerprint(cp.Org)
296		if cp.EndSeq > 0 {
297			if cp.EndSeq > len(st.audit) {
298				return nil, fmt.Errorf("%w: end sequence %d beyond %d", ErrInvalidRange, cp.EndSeq, head)
299			}
300			wantFP = st.audit[cp.EndSeq-1].Fingerprint
301		}
302		if cp.Fingerprint != wantFP {
303			return nil, fmt.Errorf("%w: checkpoint fingerprint does not match the chain at sequence %d", ErrInvalidRange, cp.EndSeq)
304		}
305		if nextSeq == 0 {
306			return &AuditPage{Org: cp.Org, BeginSeq: 1, EndSeq: cp.EndSeq, Checkpoint: cp}, nil
307		}
308		if nextSeq > cp.EndSeq+1 {
309			return nil, fmt.Errorf("%w: next sequence %d beyond pinned range ending at %d", ErrInvalidRange, nextSeq, cp.EndSeq)
310		}
311		if nextSeq == cp.EndSeq+1 {
312			return &AuditPage{Org: cp.Org, BeginSeq: nextSeq, EndSeq: cp.EndSeq, Checkpoint: cp}, nil
313		}
314		return s.auditPageLocked(cp.Org, nextSeq, cp.EndSeq, wantFP, pageSize, kind, subjectID), nil
315	}
316	
317	// auditPageLocked scans forward collecting up to pageSize matching records
318	// and computes the next-page cursor. It does not stop at pageSize raw
319	// records: filtering happens within the pinned [start,end] window.
320	func (s *Store) auditPageLocked(org string, startSeq, endSeq int, endFP string, pageSize int, kind, subjectID string) *AuditPage {
321		st := s.orgs[org]
322		out := make([]AuditRecord, 0, pageSize)
323		i := startSeq
324		for ; i <= endSeq && len(out) < pageSize; i++ {
325			r := st.audit[i-1]
326			if recordMatches(r, kind, subjectID) {
327				out = append(out, *cloneRecord(r))
328			}
329		}
330		next := 0
331		if i <= endSeq {
332			next = i
333		}
334		return &AuditPage{
335			Org:        org,
336			Records:    out,
337			BeginSeq:   startSeq,
338			EndSeq:     endSeq,
339			Next:       next,
340			Checkpoint: Checkpoint{Org: org, EndSeq: endSeq, Fingerprint: endFP},
341		}
342	}
343	
344	// AuditExport returns detached copies of the complete records through
345	// endSeq, suitable for offline verification. endSeq <= 0 means everything
346	// currently stored. An organization with no records yields an empty slice
347	// together with its sequence-0 checkpoint.
348	func (s *Store) AuditExport(org string, endSeq int) (records []AuditRecord, cp Checkpoint, err error) {
349		if org == "" {
350			return nil, Checkpoint{}, ErrMissingOrganization
351		}
352		s.mu.Lock()
353		defer s.mu.Unlock()
354		st := s.orgLocked(org)
355		head := len(st.audit)
356		if endSeq <= 0 {
357			endSeq = head
358		}
359		if endSeq > head {
360			return nil, Checkpoint{}, fmt.Errorf("%w: end sequence %d beyond %d", ErrInvalidRange, endSeq, head)
361		}
362		if endSeq < 0 {
363			return nil, Checkpoint{}, fmt.Errorf("%w: end sequence must be >= 0, got %d", ErrInvalidPage, endSeq)
364		}
365		// The checkpoint fingerprints the final exported record, not the
366		// possibly later current head.
367		fingerprint := genesisFingerprint(org)
368		if endSeq > 0 {
369			fingerprint = st.audit[endSeq-1].Fingerprint
370		}
371		out := make([]AuditRecord, 0, endSeq)
372		for i := 0; i < endSeq; i++ {
373			out = append(out, *cloneRecord(st.audit[i]))
374		}
375		return out, Checkpoint{Org: org, EndSeq: endSeq, Fingerprint: fingerprint}, nil
376	}
377	
378	// VerifyAudit validates an exported record set entirely without a Store.
379	// The caller separately retains the organization, end sequence and
380	// fingerprint they expect. It rejects any modified field, missing middle or
381	// tail record, swapped order, and record spliced in from another
382	// organization. Empty or nil records validate exactly when the checkpoint
383	// is the organization's genesis (end sequence 0).
384	func VerifyAudit(org string, records []AuditRecord, cp Checkpoint) error {
385		if org == "" {
386			return ErrMissingOrganization
387		}
388		if cp.Org != "" && cp.Org != org {
389			return fmt.Errorf("%w: checkpoint organization %q does not match %q", ErrInvalidRange, cp.Org, org)
390		}
391		genesis := genesisFingerprint(org)
392		if len(records) == 0 {
393			if cp.EndSeq != 0 || cp.Fingerprint != genesis {
394				return fmt.Errorf("%w: empty records but checkpoint claims end sequence %d", ErrInvalidRange, cp.EndSeq)
395			}
396			return nil
397		}
398		if cp.EndSeq != len(records) {
399			return fmt.Errorf("%w: have %d records, checkpoint ends at %d", ErrInvalidRange, len(records), cp.EndSeq)
400		}
401		prev := genesis
402		for i, r := range records {
403			wantSeq := i + 1
404			if r.Org != org {
405				return fmt.Errorf("%w: record %d belongs to organization %q", ErrInvalidRange, wantSeq, r.Org)
406			}
407			if r.Seq != wantSeq {
408				return fmt.Errorf("%w: record %d has sequence %d", ErrInvalidRange, wantSeq, r.Seq)
409			}
410			if r.PrevFingerprint != prev {
411				return fmt.Errorf("%w: record %d breaks the chain", ErrInvalidRange, wantSeq)
412			}
413			wantFP := fingerprintFor(&r)
414			if r.Fingerprint != wantFP {
415				return fmt.Errorf("%w: record %d fingerprint mismatch", ErrInvalidRange, wantSeq)
416			}
417			if r.Kind == AuditPolicyChange {
418				if r.Change == nil || r.Decision != nil {
419					return fmt.Errorf("%w: record %d payload does not match its category", ErrInvalidRange, wantSeq)
420				}
421			} else if r.Kind == AuditDecision {
422				if r.Decision == nil || r.Change != nil {
423					return fmt.Errorf("%w: record %d payload does not match its category", ErrInvalidRange, wantSeq)
424				}
425			} else {
426				return fmt.Errorf("%w: record %d has unknown category %q", ErrInvalidRange, wantSeq, r.Kind)
427			}
428			prev = r.Fingerprint
429		}
430		last := records[len(records)-1]
431		if last.Fingerprint != cp.Fingerprint {
432			return fmt.Errorf("%w: checkpoint fingerprint does not match the final record", ErrInvalidRange)
433		}
434		return nil
435	}
436	
437	// RecheckDecision re-evaluates the request stored in an organization's
438	// decision record against the policy version that decision actually used.
439	// Later publishes or rollbacks cannot alter the result. Non-decision
440	// records and missing sequences return distinguishable errors.
441	func (s *Store) RecheckDecision(org string, seq int) (Decision, error) {
442		if org == "" {
443			return Decision{}, ErrMissingOrganization
444		}
445		if seq < 1 {
446			return Decision{}, fmt.Errorf("%w: sequence %d", ErrAuditNotFound, seq)
447		}
448		s.mu.Lock()
449		defer s.mu.Unlock()
450		st, ok := s.orgs[org]
451		if !ok || seq > len(st.audit) {
452			return Decision{}, fmt.Errorf("%w: organization %q has no audit sequence %d", ErrAuditNotFound, org, seq)
453		}
454		rec := st.audit[seq-1]
455		if rec.Kind != AuditDecision || rec.Decision == nil {
456			return Decision{}, fmt.Errorf("%w: sequence %d is %s", ErrAuditNotADecision, seq, rec.Kind)
457		}
458		req := rec.Decision.Request
459		version := rec.Decision.Decision.Version
460		if version == 0 {
461			// The original decision evaluated no published version: requests
462			// rejected at the envelope, or an organization with no publish yet.
463			if d, ok := checkRequest(org, req); !ok {
464				return d, nil
465			}
466			return Decision{Allowed: false, Reason: "organization has no published version"}, nil
467		}
468		src, ok := st.versions[version]
469		if !ok {
470			// A decision's version is immutable and never deleted; its absence
471			// indicates store tampering rather than normal operation.
472			return Decision{}, fmt.Errorf("%w: decision used version %d, which no longer exists", ErrVersionNotFound, version)
473		}
474		return evaluate(req, append([]Policy(nil), src...), version), nil
475	}
476

