1	// This file implements organization-scoped policy publishing, rollback,
2	// and review on top of the decision core. Each organization versions its
3	// own policy set independently; all state is in-memory and lives until
4	// the service instance ends.
5	package darksafe
6	
7	import (
8		"errors"
9		"fmt"
10		"sort"
11		"strings"
12		"sync"
13	)
14	
15	// Effect is the outcome a policy produces when it matches a request.
16	type Effect string
17	
18	const (
19		EffectAllow Effect = "allow"
20		EffectDeny  Effect = "deny"
21	)
22	
23	// Policy binds one subject and one action to a scope with an effect.
24	type Policy struct {
25		ID        string
26		Subject   string
27		Action    string
28		Scope     string
29		Effect    Effect
30		Recursive bool // false: only the exact scope; true: the scope and its descendants
31	}
32	
33	// Sentinel errors so callers can distinguish failure causes with errors.Is.
34	var (
35		// ErrVersionConflict means the caller's expected current version is stale.
36		ErrVersionConflict = errors.New("darksafe: version conflict")
37		// ErrVersionNotFound means the requested historical version does not exist.
38		ErrVersionNotFound = errors.New("darksafe: version not found")
39		// ErrInvalidPolicySet means the submitted policy set failed validation.
40		ErrInvalidPolicySet = errors.New("darksafe: invalid policy set")
41		// ErrMissingOrganization means an operation was called without an organization.
42		ErrMissingOrganization = errors.New("darksafe: organization is required")
43	)
44	
45	// OrgRequest is an access request evaluated against one organization's
46	// published policies. Both organizations must equal the decision organization.
47	type OrgRequest struct {
48		SubjectOrg  string
49		ResourceOrg string
50		Subject     Subject
51		Resource    Resource
52		Action      string
53	}
54	
55	// Store holds every organization's published policy versions. It is safe
56	// for concurrent use and keeps all state in memory.
57	type Store struct {
58		mu   sync.Mutex
59		orgs map[string]*orgState
60	}
61	
62	type orgState struct {
63		current  int              // 0 means nothing published yet
64		versions map[int][]Policy // immutable snapshots per version
65		audit    []*AuditRecord   // gapless, append-only audit chain
66	}
67	
68	// NewStore returns an empty Store.
69	func NewStore() *Store {
70		return &Store{orgs: make(map[string]*orgState)}
71	}
72	
73	func (s *Store) orgLocked(name string) *orgState {
74		st, ok := s.orgs[name]
75		if !ok {
76			st = &orgState{versions: make(map[int][]Policy)}
77			s.orgs[name] = st
78		}
79		return st
80	}
81	
82	// CurrentVersion reports the organization's current version, 0 if it has
83	// never published.
84	func (s *Store) CurrentVersion(org string) int {
85		s.mu.Lock()
86		defer s.mu.Unlock()
87		if st, ok := s.orgs[org]; ok {
88			return st.current
89		}
90		return 0
91	}
92	
93	// Publish validates and publishes a complete policy set as the next
94	// version. expectedVersion must equal the organization's current version;
95	// on any validation or version failure nothing changes and no version
96	// number is consumed.
97	func (s *Store) Publish(org string, expectedVersion int, policies []Policy) (int, error) {
98		if org == "" {
99			return 0, ErrMissingOrganization
100		}
101		snapshot, err := validatePolicies(policies)
102		if err != nil {
103			return 0, err
104		}
105		s.mu.Lock()
106		defer s.mu.Unlock()
107		st := s.orgLocked(org)
108		if expectedVersion != st.current {
109			return 0, fmt.Errorf("%w: expected %d, current is %d", ErrVersionConflict, expectedVersion, st.current)
110		}
111		st.current++
112		st.versions[st.current] = snapshot
113		// The change and its audit record become visible together; a failed
114		// publish never reaches this point and leaves no record.
115		st.appendAuditLocked(org, AuditPolicyChange, &PolicyChange{
116			Version:       st.current,
117			Policies:      snapshot,
118			SourceVersion: 0,
119			RolledBack:    false,
120		}, nil)
121		return st.current, nil
122	}
123	
124	// Rollback republishes the full content of an existing historical version
125	// as a new version. History is never deleted or rewritten.
126	func (s *Store) Rollback(org string, expectedVersion, targetVersion int) (int, error) {
127		if org == "" {
128			return 0, ErrMissingOrganization
129		}
130		s.mu.Lock()
131		defer s.mu.Unlock()
132		st := s.orgLocked(org)
133		src, ok := st.versions[targetVersion]
134		if !ok {
135			return 0, fmt.Errorf("%w: organization %q has no version %d", ErrVersionNotFound, org, targetVersion)
136		}
137		if expectedVersion != st.current {
138			return 0, fmt.Errorf("%w: expected %d, current is %d", ErrVersionConflict, expectedVersion, st.current)
139		}
140		st.current++
141		snapshot := append([]Policy(nil), src...)
142		st.versions[st.current] = snapshot
143		// A rollback record names the source version in addition to carrying
144		// the full content of the new version.
145		st.appendAuditLocked(org, AuditPolicyChange, &PolicyChange{
146			Version:       st.current,
147			Policies:      snapshot,
148			SourceVersion: targetVersion,
149			RolledBack:    true,
150		}, nil)
151		return st.current, nil
152	}
153	
154	// Policies returns a copy of the full policy set of one version. Mutating
155	// the result does not affect published content.
156	func (s *Store) Policies(org string, version int) ([]Policy, error) {
157		s.mu.Lock()
158		defer s.mu.Unlock()
159		st, ok := s.orgs[org]
160		if !ok {
161			return nil, fmt.Errorf("%w: organization %q has no version %d", ErrVersionNotFound, org, version)
162		}
163		src, ok := st.versions[version]
164		if !ok {
165			return nil, fmt.Errorf("%w: organization %q has no version %d", ErrVersionNotFound, org, version)
166		}
167		return append([]Policy(nil), src...), nil
168	}
169	
170	// Decide evaluates a request against the organization's current version.
171	// The whole decision uses that single version's snapshot, and the version
172	// actually used is reported in Decision.Version.
173	//
174	// Every call with a non-empty decision organization leaves a decision
175	// record, including envelope rejections (disabled subject, missing fields,
176	// organization mismatch) and the no-published-version denial. A call with
177	// an empty organization rejects as before and creates no record, because
178	// there is no organization to attribute it to. The evaluation and record
179	// append are atomic: a concurrent publish can never make the recorded
180	// version differ from the version that was evaluated.
181	func (s *Store) Decide(org string, req OrgRequest) Decision {
182		if org == "" {
183			d, _ := checkRequest(org, req)
184			return d
185		}
186		if d, ok := checkRequest(org, req); !ok {
187			s.mu.Lock()
188			st := s.orgLocked(org)
189			st.appendAuditLocked(org, AuditDecision, nil, &DecisionRecord{Request: req, Decision: d})
190			s.mu.Unlock()
191			return d
192		}
193		s.mu.Lock()
194		defer s.mu.Unlock()
195		st := s.orgLocked(org)
196		version := st.current
197		var d Decision
198		if version == 0 {
199			d = Decision{Allowed: false, Reason: "organization has no published version"}
200		} else {
201			d = evaluate(req, st.versions[version], version)
202		}
203		st.appendAuditLocked(org, AuditDecision, nil, &DecisionRecord{Request: req, Decision: d})
204		return d
205	}
206	
207	// Review re-evaluates a request against a specific historical version.
208	// Later publishes or rollbacks cannot change its outcome; a version that
209	// does not exist is a denial with a reason, never a silent fallback to
210	// the current version.
211	func (s *Store) Review(org string, version int, req OrgRequest) Decision {
212		if d, ok := checkRequest(org, req); !ok {
213			return d
214		}
215		s.mu.Lock()
216		var policies []Policy
217		found := false
218		if st, ok := s.orgs[org]; ok {
219			if src, ok := st.versions[version]; ok {
220				policies = append([]Policy(nil), src...)
221				found = true
222			}
223		}
224		s.mu.Unlock()
225		if !found {
226			return Decision{Allowed: false, Reason: fmt.Sprintf("version %d not found", version)}
227		}
228		return evaluate(req, policies, version)
229	}
230	
231	// checkRequest validates the request envelope. Every failure is a denial
232	// with a distinguishable reason.
233	func checkRequest(org string, req OrgRequest) (Decision, bool) {
234		switch {
235		case org == "":
236			return Decision{Allowed: false, Reason: "missing decision organization"}, false
237		case req.SubjectOrg == "":
238			return Decision{Allowed: false, Reason: "missing subject organization"}, false
239		case req.ResourceOrg == "":
240			return Decision{Allowed: false, Reason: "missing resource organization"}, false
241		case req.Subject.ID == "":
242			return Decision{Allowed: false, Reason: "missing subject id"}, false
243		case req.Resource.ID == "":
244			return Decision{Allowed: false, Reason: "missing resource id"}, false
245		case req.Action == "":
246			return Decision{Allowed: false, Reason: "missing action"}, false
247		}
248		if req.SubjectOrg != org || req.ResourceOrg != org {
249			return Decision{Allowed: false, Reason: "organization mismatch"}, false
250		}
251		if err := validateScope(req.Resource.Scope); err != nil {
252			return Decision{Allowed: false, Reason: "invalid scope: " + err.Error()}, false
253		}
254		if req.Subject.Disabled {
255			return Decision{Allowed: false, Reason: "subject is disabled"}, false
256		}
257		return Decision{}, true
258	}
259	
260	// evaluate applies one version's policies to a request. Subject roles are
261	// deliberately ignored: only the selected version's policies decide.
262	func evaluate(req OrgRequest, policies []Policy, version int) Decision {
263		seen := make(map[string]struct{})
264		denied := false
265		allowed := false
266		for _, p := range policies {
267			if p.Subject != req.Subject.ID || p.Action != req.Action {
268				continue
269			}
270			if !scopeMatches(p, req.Resource.Scope) {
271				continue
272			}
273			seen[p.ID] = struct{}{}
274			switch p.Effect {
275			case EffectDeny:
276				denied = true
277			case EffectAllow:
278				allowed = true
279			}
280		}
281		matched := make([]string, 0, len(seen))
282		for id := range seen {
283			matched = append(matched, id)
284		}
285		sort.Strings(matched)
286		switch {
287		case denied:
288			return Decision{Allowed: false, Reason: "matched deny policy", Matched: matched, Version: version}
289		case allowed:
290			return Decision{Allowed: true, Reason: "matched allow policy", Matched: matched, Version: version}
291		default:
292			return Decision{Allowed: false, Reason: "no matching allow policy", Matched: matched, Version: version}
293		}
294	}
295	
296	// scopeMatches reports whether a policy's scope covers the request scope.
