1	// This file implements offline review of a single audited decision. It
2	// works solely from exported audit material: the complete record export,
3	// the separately retained checkpoint, and a target sequence. No Store is
4	// created or restored, so an organization can confirm why an access was
5	// allowed or denied long after the service instance that decided it has
6	// ended.
7	//
8	// The complete input must first validate as an audit chain. The policy
9	// version a decision actually used is recovered exclusively from policy
10	// change records preceding that decision within the same organization's
11	// export; later publishes or rollbacks, and a wider later export, cannot
12	// change the recomputed result.
13	package darksafe
14	
15	import "fmt"
16	
17	// OfflineDecisionReview compares the decision stored in an audited record
18	// with a decision recomputed purely from the exported material.
19	type OfflineDecisionReview struct {
20		// Seq is the reviewed decision record's sequence.
21		Seq int
22		// Original is the decision preserved in the audited record.
23		Original Decision
24		// Recomputed is the decision evaluated again offline from the saved
25		// request and the policy version it originally used.
26		Recomputed Decision
27		// Consistent reports whether both decisions agree on every field
28		// (allowance, reason, matched policies and version), treating a nil
29		// matched list and an empty matched list as the same.
30		Consistent bool
31	}
32	
33	// RecheckDecisionOffline re-evaluates one decision record offline. org is
34	// the organization name, records is its complete export starting at
35	// sequence 1 (a valid prefix is sufficient when paired with its own
36	// checkpoint), cp is the separately saved checkpoint, and seq identifies
37	// the decision record to review. The call is read-only: it neither mutates
38	// the supplied material nor appends audit records, and the returned
39	// decisions are detached from the input slices.
40	//
41	// The entire export is chain-validated before any result is produced;
42	// tampering anywhere, including in records after the target, fails the
43	// review. Distinguishable errors follow the other audit entry points:
44	// ErrMissingOrganization for an empty organization, ErrAuditNotFound for a
45	// non-positive or absent target sequence, and ErrAuditNotADecision when the
46	// target is a policy change record. When the saved decision names a
47	// policy version whose full content has no change record before the
48	// target, ErrVersionNotFound is returned; a newer version is never
49	// substituted.
50	func RecheckDecisionOffline(org string, records []AuditRecord, cp Checkpoint, seq int) (OfflineDecisionReview, error) {
51		if org == "" {
52			return OfflineDecisionReview{}, ErrMissingOrganization
53		}
54		// Validate the whole export first. A subject-filtered page, a fragment
55		// missing the beginning, or a checkpoint that does not pin the records
56		// all fail here, as does any corruption after the target.
57		if err := VerifyAudit(org, records, cp); err != nil {
58			return OfflineDecisionReview{}, err
59		}
60		if seq < 1 {
61			return OfflineDecisionReview{}, fmt.Errorf("%w: sequence %d", ErrAuditNotFound, seq)
62		}
63		if seq > len(records) {
64			return OfflineDecisionReview{}, fmt.Errorf("%w: export ends at %d, no sequence %d", ErrAuditNotFound, len(records), seq)
65		}
66		rec := &records[seq-1]
67		if rec.Kind != AuditDecision || rec.Decision == nil {
68			return OfflineDecisionReview{}, fmt.Errorf("%w: sequence %d is %s", ErrAuditNotADecision, seq, rec.Kind)
69		}
70	
71		original := cloneDecisionValue(rec.Decision.Decision)
72		req := rec.Decision.Request
73		if len(req.Subject.Roles) > 0 {
74			req.Subject.Roles = append([]string(nil), req.Subject.Roles...)
75		}
76		version := original.Version
77	
78		var recomputed Decision
79		if version == 0 {
80			// The original evaluation used no published version: replay the
81			// envelope rejections exactly, then the not-yet-published denial.
82			if d, ok := checkRequest(org, req); !ok {
83				recomputed = d
84			} else {
85				recomputed = Decision{Allowed: false, Reason: "organization has no published version"}
86			}
87		} else {
88			// The version's full content must travel in a same-organization
89			// policy change record positioned before the decision.
90			policies, found := policiesBefore(records, seq-1, version)
91			if !found {
92				if _, later := policiesBefore(records, len(records), version); later {
93					return OfflineDecisionReview{}, fmt.Errorf(
94						"%w: decision at sequence %d used version %d, whose change record appears only after it",
95						ErrVersionNotFound, seq, version)
96				}
97				return OfflineDecisionReview{}, fmt.Errorf(
98					"%w: decision at sequence %d used version %d, which has no policy change record in the export",
99					ErrVersionNotFound, seq, version)
100			}
101			recomputed = evaluate(req, policies, version)
102		}
103	
104		return OfflineDecisionReview{
105			Seq:        seq,
106			Original:   original,
107			Recomputed: recomputed,
108			Consistent: decisionsEqual(original, recomputed),
109		}, nil
110	}
111	
112	// policiesBefore searches records[:limit] for the policy change record that
113	// published version and returns a detached copy of its full content. The
114	// gapless chain validation guarantees records are in sequence order.
115	func policiesBefore(records []AuditRecord, limit, version int) ([]Policy, bool) {
116		for i := 0; i < limit; i++ {
117			r := &records[i]
118			if r.Kind != AuditPolicyChange || r.Change == nil {
119				continue
120			}
121			if r.Change.Version == version {
122				return append([]Policy(nil), r.Change.Policies...), true
123			}
124		}
125		return nil, false
126	}
127	
128	// cloneDecisionValue returns a decision detached from the input's matched
129	// slice.
130	func cloneDecisionValue(d Decision) Decision {
131		if len(d.Matched) > 0 {
132			d.Matched = append([]string(nil), d.Matched...)
133		}
134		return d
135	}
136	
137	// decisionsEqual compares every decision field. A nil matched list and an
138	// empty matched list describe the same set of hits.
139	func decisionsEqual(a, b Decision) bool {
140		if a.Allowed != b.Allowed || a.Reason != b.Reason || a.Version != b.Version {
141			return false
142		}
143		if len(a.Matched) == 0 && len(b.Matched) == 0 {
144			return true
145		}
146		if len(a.Matched) != len(b.Matched) {
147			return false
148		}
149		for i := range a.Matched {
150			if a.Matched[i] != b.Matched[i] {
151				return false
152			}
153		}
154		return true
155	}
