253	func TestAuditQueryFiltersAndPaging(t *testing.T) {
254		s := NewStore()
255		s.Publish("acme", 0, nil)                                      // seq 1
256		s.Decide("acme", request("acme", "u1", "r1", "org/a", "read")) // seq 2
257		s.Decide("acme", request("acme", "u2", "r1", "org/a", "read")) // seq 3
