262		changes := drainAudit(t, s, "acme", AuditPolicyChange, "")
263		if len(changes) != 2 {
264			t.Fatalf("changes = %d, want 2", len(changes))
265		}
266		// Subject filter returns that subject's decisions only, never changes.
267		u1 := drainAudit(t, s, "acme", "", "u1")
268		if len(u1) != 2 {
269			t.Fatalf("u1 records = %d, want 2", len(u1))
270		}
