306	func TestAuditQueryPinsRangeAgainstLaterAppends(t *testing.T) {
307		s := NewStore()
308		s.Publish("acme", 0, nil)
309		s.Decide("acme", request("acme", "u1", "r1", "org/a", "read"))
310		first, err := s.AuditQuery("acme", 1, 1, "", "")
311		if err != nil {
312			t.Fatal(err)
313		}
314		if first.Checkpoint.EndSeq != 2 {
315			t.Fatalf("initial end = %d, want 2", first.Checkpoint.EndSeq)
316		}
317		// Records appended after the first query must not mix into its pages.
318		s.Publish("acme", 1, nil)
319		s.Decide("acme", request("acme", "u9", "r1", "org/a", "read"))
320		second, err := s.AuditPage(first.Checkpoint, first.Next, 10, "", "")
321		if err != nil {
322			t.Fatal(err)
323		}
324		var seqs []int
325		seqs = append(seqs, first.Records[0].Seq)
326		for _, r := range second.Records {
327			seqs = append(seqs, r.Seq)
328		}
329		if !reflect.DeepEqual(seqs, []int{1, 2}) {
330			t.Fatalf("later records leaked into pinned query: %v", seqs)
331		}
332		if second.EndSeq != 2 {
333			t.Fatalf("page end = %d, want pinned 2", second.EndSeq)
334		}
335		// A fresh query sees the new tail.
336		fresh, err := s.AuditQuery("acme", 1, 10, "", "")
337		if err != nil {
338			t.Fatal(err)
339		}
340		if fresh.Checkpoint.EndSeq != 4 || len(fresh.Records) != 4 {
341			t.Fatalf("fresh query = %+v, want 4 records ending at 4", fresh)
342		}
343	}
