package darksafe

import (
	"bytes"
	"encoding/json"
	"strconv"
	"unicode/utf8"
)

// auditHashEncoder writes the canonical, byte-preserving representation
// that audit fingerprints are computed over.
//
// The encoding is byte-identical to encoding/json's output for every string
// that is valid UTF-8, so fingerprints of ordinary content are unchanged.
// Strings containing invalid UTF-8 bytes are encoded with a per-byte escape
// (\xNN) that no legal JSON string can produce, so two different raw strings
// can never hash to the same value even though JSON would render both as the
// same replacement character.
type auditHashEncoder struct {
	buf bytes.Buffer
}

func (e *auditHashEncoder) writeRaw(s string) {
	e.buf.WriteString(s)
}

func (e *auditHashEncoder) writeString(s string) {
	e.buf.Write(encodeAuditString(s))
}

func (e *auditHashEncoder) writeInt(v int) {
	e.buf.WriteString(strconv.Itoa(v))
}

func (e *auditHashEncoder) writeBool(v bool) {
	if v {
		e.buf.WriteString("true")
	} else {
		e.buf.WriteString("false")
	}
}

