func (e *auditHashEncoder) writeStringSlice(v []string) {
	if v == nil {
		e.buf.WriteString("null")
		return
	}
	e.buf.WriteByte('[')
	for i, s := range v {
		if i > 0 {
			e.buf.WriteByte(',')
		}
		e.writeString(s)
	}
	e.buf.WriteByte(']')
}

