			// A Go string always marshals; failure here is a programming
			// error, not user input.
			panic(fmt.Errorf("darksafe: audit string must encode: %w", err))
		}
		return b
	}
	var buf bytes.Buffer
	buf.WriteByte('"')
	for i := 0; i < len(s); {
		b := s[i]
		if b < utf8.RuneSelf {
			// ASCII: escape exactly as encoding/json does.
			switch b {
			case '"', '\\':
				buf.WriteByte('\\')
				buf.WriteByte(b)
			case '\n':
				buf.WriteString(`\n`)
			case '\r':
				buf.WriteString(`\r`)
			case '\t':
				buf.WriteString(`\t`)
			case '\b':
				buf.WriteString(`\b`)
			case '\f':
				buf.WriteString(`\f`)
			default:
				if b < 0x20 || b == '<' || b == '>' || b == '&' {
					buf.WriteString(`\u00`)
					buf.WriteByte(auditHexDigits[b>>4])
					buf.WriteByte(auditHexDigits[b&0xF])
				} else {
					buf.WriteByte(b)
				}
			}
			i++
			continue
		}
		c, size := utf8.DecodeRuneInString(s[i:])
		if c == utf8.RuneError && size == 1 {
			// Preserve the raw invalid byte distinctly.
			buf.WriteString(`\x`)
			buf.WriteByte(auditHexDigits[b>>4])
			buf.WriteByte(auditHexDigits[b&0xF])
			i++
			continue
		}
		if c == ' ' || c == ' ' {
			buf.WriteString(`\u202`)
			buf.WriteByte(auditHexDigits[c&0xF])
			i += size
			continue
		}
		buf.WriteString(s[i : i+size])
		i += size
	}
	buf.WriteByte('"')
	return buf.Bytes()
}

