	s := NewStore()
	// Policy fields with invalid bytes: validation must still accept them.
	policies := []Policy{{
		ID:      "p\xff",
		Subject: "u\xff",
		Action:  "read\xfe",
		Scope:   "org/a\x80",
		Effect:  EffectAllow,
	}}
