	req := OrgRequest{
		SubjectOrg:  "acme",
		ResourceOrg: "acme",
		Subject: Subject{
			ID:    "中\xff文",
			Kind:  "user\xab",
			Roles: []string{"role\xff", "角色\xfe"},
		},
		Resource: Resource{ID: "r\xff", Scope: "org/a\x80"},
		Action:   "read\x99",
	}
	d := s.Decide("acme", req)
	if !d.Allowed {
		t.Fatalf("decision = %+v, want allowed", d)
	}

